1248	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1249	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1250	function dereference(
1251	  node: Record<string, unknown>,
1252	  ctx: ImportCtx,
1253	  where: string,
1254	  refChain: readonly string[],
1255	): { target: unknown; where: string; refChain: readonly string[] } | null {
1256	  if (!hasOwnKey(node, '$ref')) {
1257	    return null;
1258	  }
1259	  if (Object.keys(node).length !== 1) {
1260	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1261	  }
1262	  const ref = node.$ref;
1263	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1264	    importFail(
1265	      ctx,
1266	      where,
1267	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1268	    );
1269	  }
1270	  if (refChain.includes(ref as string)) {
1271	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1272	  }
1273	  const fragment = (ref as string).slice(1);
1274	  let target: unknown = ctx.doc;
1275	  if (fragment !== '') {
1276	    if (!fragment.startsWith('/')) {
1277	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1278	    }
1279	    const segments = fragment
1280	      .slice(1)
1281	      .split('/')
1282	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1283	    let traversed = '#';
1284	    for (const segment of segments) {
1285	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1286	      if (Array.isArray(target)) {
1287	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1288	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1289	        }
1290	        target = target[Number(segment)];
1291	      } else if (isPlainObject(target)) {
1292	        if (!hasOwnKey(target, segment)) {
1293	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1294	        }
1295	        target = target[segment];
1296	      } else {
1297	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1298	      }
1299	    }
1300	  }
1301	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1302	}
