1304	// 解析一层或多层 $ref 并做节点级基础校验（必须是对象、nullable 仅可 false），
1305	// 返回落定的 schema 节点与其（含引用链的）位置。
1306	function resolveSchemaNode(
1307	  rawNode: unknown,
1308	  ctx: ImportCtx,
1309	  where: string,
1310	  refChain: readonly string[],
1311	): { n: Record<string, unknown>; nodeWhere: string; chain: readonly string[] } {
1312	  let node = rawNode;
1313	  let nodeWhere = where;
1314	  let chain = refChain;
1315	  // 引用节点可以层层指向另一个引用节点
1316	  for (;;) {
1317	    if (!isPlainObject(node)) {
1318	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1319	    }
1320	    const ref = dereference(node, ctx, nodeWhere, chain);
1321	    if (!ref) {
1322	      break;
1323	    }
1324	    node = ref.target;
1325	    nodeWhere = ref.where;
1326	    chain = ref.refChain;
1327	  }
1328	  const n = node as Record<string, unknown>;
1329	  // nullable 仅允许 false（等同不声明，忽略）；true 属于非法值
1330	  if (hasOwnKey(n, 'nullable') && n.nullable !== false) {
1331	    importFail(ctx, `${nodeWhere}.nullable`, `仅支持 false（或不声明），收到 ${JSON.stringify(n.nullable)}`);
1332	  }
1333	  return { n, nodeWhere, chain };
1334	}
