1336	// 组合节点键校验（仅 allOf 与注释）并取出非空 allOf 数组
1337	function comboList(n: Record<string, unknown>, ctx: ImportCtx, nodeWhere: string): unknown[] {
1338	  for (const key of Object.keys(n)) {
1339	    if (key !== 'allOf' && !OPENAPI_ANNOTATION_KEYS.has(key)) {
1340	      importFail(
1341	        ctx,
1342	        nodeWhere,
1343	        `组合节点仅允许 allOf 及注释（title/description/example/nullable），含未支持的关键字 "${key}"`,
1344	      );
1345	    }
1346	  }
1347	  const list = n.allOf;
1348	  if (!Array.isArray(list) || list.length === 0) {
