1354	// 递归收集（可能嵌套的）allOf 子树的全部对象叶分支：组合节点只含 allOf 与
1355	// 注释，其子树展开后的叶分支即全部参与交集的分支。交集满足结合律，故展平不
1356	// 改变接受集合，也使成功/拒绝结论与分支顺序、嵌套分组无关。loc 保留每个叶分
1357	// 支的精确位置（含嵌套 allOf 下标与 $ref 链），用于来源定位。
1358	interface ObjectLeaf {
1359	  readonly rule: NormObject;
1360	  readonly loc: string;
1361	}
