1363	function collectObjectLeaves(
1364	  list: readonly unknown[],
1365	  ctx: ImportCtx,
1366	  parentWhere: string,
1367	  chain: readonly string[],
1368	): ObjectLeaf[] {
1369	  const leaves: ObjectLeaf[] = [];
1370	  list.forEach((raw, i) => {
1371	    const branchWhere = `${parentWhere}.allOf[${i}]`;
1372	    const { n, nodeWhere, chain: ch } = resolveSchemaNode(raw, ctx, branchWhere, chain);
1373	    if (hasOwnKey(n, 'allOf')) {
1374	      leaves.push(...collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, ch));
1375	      return;
1376	    }
1377	    const rule = buildSimpleNorm(n, ctx, nodeWhere, ch);
1378	    if (rule.kind !== 'object') {
1379	      importFail(ctx, nodeWhere, `仅支持纯对象 allOf 组合，该分支最终类型为 ${rule.kind}`);
1380	    }
1381	    leaves.push({ rule: rule as NormObject, loc: nodeWhere });
1382	  });
1383	  return leaves;
1384	}
