1386	// schema（或引用链尽头的 schema）-> 规范化规则
1387	function schemaToNorm(
1388	  rawNode: unknown,
1389	  ctx: ImportCtx,
1390	  where: string,
1391	  refChain: readonly string[],
1392	): NormRule {
1393	  const { n, nodeWhere, chain } = resolveSchemaNode(rawNode, ctx, where, refChain);
1394	
1395	  if (hasOwnKey(n, 'allOf')) {
1396	    const leaves = collectObjectLeaves(comboList(n, ctx, nodeWhere), ctx, nodeWhere, chain);
1397	    const result = intersectObjects(
1398	      leaves.map((l) => ({ rule: l.rule, loc: l.loc })),
1399	      nodeWhere,
1400	    );
1401	    // 整体空交集 与 非空但无法表达 都拒绝；reason 含冲突字段/元素与失败理由，
1402	    // loc 指向贡献该结论的叶分支（可定位的操作或定义位置）
1403	    if (result.tag === 'empty' || result.tag === 'inexpressible') {
1404	      importFail(ctx, result.loc, result.reason);
1405	    }
1406	    return result.rule;
1407	  }
1408	
1409	  return buildSimpleNorm(n, ctx, nodeWhere, chain);
1410	}
