1412	// 非组合（非 allOf）schema -> 规范化规则
1413	function buildSimpleNorm(
1414	  n: Record<string, unknown>,
1415	  ctx: ImportCtx,
1416	  nodeWhere: string,
1417	  chain: readonly string[],
1418	): NormRule {
1419	  const type = n.type;
1420	  if (
1421	    typeof type !== 'string' ||
1422	    (type !== 'object' && type !== 'array' && !OPENAPI_SCALAR_TYPES.has(type))
1423	  ) {
1424	    importFail(
1425	      ctx,
1426	      `${nodeWhere}.type`,
1427	      `必须是 "object" | "array" | "string" | "number" | "integer" | "boolean"，收到 ${JSON.stringify(n.type)}`,
1428	    );
1429	  }
1430	  const structural: readonly string[] =
1431	    type === 'object'
1432	      ? ['properties', 'required', 'additionalProperties']
1433	      : type === 'array'
1434	        ? ['items']
1435	        : [];
1436	  for (const key of Object.keys(n)) {
1437	    if (key !== 'type' && !OPENAPI_ANNOTATION_KEYS.has(key) && !structural.includes(key)) {
1438	      importFail(ctx, nodeWhere, `含未支持的关键字 "${key}"`);
1439	    }
1440	  }
1441	
1442	  if (type === 'array') {
1443	    if (!hasOwnKey(n, 'items')) {
1444	      importFail(ctx, `${nodeWhere}.items`, '数组 schema 必须声明元素规则 items');
1445	    }
1446	    return { kind: 'array', items: schemaToNorm(n.items, ctx, `${nodeWhere}.items`, chain) };
1447	  }
1448	
1449	  if (type === 'object') {
1450	    const propsRaw = n.properties;
1451	    if (propsRaw !== undefined && !isPlainObject(propsRaw)) {
1452	      importFail(ctx, `${nodeWhere}.properties`, '必须是对象（字段名 -> schema）');
1453	    }
1454	    const reqRaw = n.required;
1455	    const requiredList: string[] = [];
1456	    if (reqRaw !== undefined) {
1457	      if (!Array.isArray(reqRaw)) {
1458	        importFail(ctx, `${nodeWhere}.required`, '必须是字符串数组');
1459	      }
1460	      for (let i = 0; i < (reqRaw as unknown[]).length; i += 1) {
1461	        const item = (reqRaw as unknown[])[i];
1462	        if (typeof item !== 'string') {
1463	          importFail(ctx, `${nodeWhere}.required[${i}]`, `必须是字符串，收到 ${JSON.stringify(item)}`);
1464	        }
1465	        if (requiredList.includes(item as string)) {
1466	          importFail(ctx, `${nodeWhere}.required`, `含重复项 ${JSON.stringify(item)}`);
1467	        }
1468	        requiredList.push(item as string);
1469	      }
1470	    }
1471	    const props = new Map<string, NormRule>();
1472	    if (propsRaw !== undefined) {
1473	      for (const [name, sub] of Object.entries(propsRaw as Record<string, unknown>)) {
1474	        props.set(
1475	          name,
1476	          schemaToNorm(sub, ctx, `${nodeWhere}.properties[${JSON.stringify(name)}]`, chain),
1477	        );
1478	      }
1479	    }
1480	    for (const name of requiredList) {
1481	      if (!props.has(name)) {
1482	        importFail(ctx, `${nodeWhere}.required`, `${JSON.stringify(name)} 未在同层 properties 中声明`);
1483	      }
1484	    }
1485	    const addlRaw = n.additionalProperties;
1486	    if (addlRaw !== undefined && typeof addlRaw !== 'boolean') {
1487	      importFail(
1488	        ctx,
1489	        `${nodeWhere}.additionalProperties`,
1490	        `仅支持布尔值，收到 ${JSON.stringify(addlRaw)}`,
1491	      );
1492	    }
1493	    // OpenAPI 缺省允许未声明字段；输出时显式写出
1494	    return { kind: 'object', props, required: new Set(requiredList), addl: addlRaw !== false };
1495	  }
1496	
1497	  return { kind: type as 'string' | 'number' | 'integer' | 'boolean' };
1498	}
