1518	// 参与交集的一个规则分支：rule 是其规范化规则，loc 是该规则在文档中的精确
1519	// 来源位置（对象取 allOf 叶分支位置、字段取 ...properties["名"]、元素取 ...items），
1520	// 用于在拒绝时给出可定位的操作或定义位置。
1521	interface RuleBranch {
1522	  readonly rule: NormRule;
1523	  readonly loc: string;
1524	}
