1938	// 从快照无损重建出来、供重新判定/重放的一条请求
1939	interface SnapshotRequest {
1940	  readonly id: number;
1941	  readonly method: string;
1942	  // 含查询串的原始请求目标（重放时原样发送；verify 不使用）
1943	  readonly target: string;
1944	  // target 去掉查询串后的字面路径（已核对与记录 path 一致）
1945	  readonly path: string;
1946	  // 按在线顺序成对保留的原始请求头（重放时过滤后发送；verify 仅用于取 Content-Type）
1947	  readonly rawHeaders: readonly string[];
1948	  // 在线顺序第一项 Content-Type 头值（名称不分大小写）；没有则为 undefined
1949	  readonly contentType: string | undefined;
1950	  readonly body: Buffer;
1951	}
