1953	// utf-8 文本必须能无损编码往返：孤立代理项（lone surrogate）按 UTF-8 编码时
1954	// 会被替换为 U+FFFD，即使替换后的字节数恰好与 bodyBytes 吻合也不再是原始字节，
1955	// 必须拒绝（verify 与 replay 共用此校验）。
1956	function hasLoneSurrogate(text: string): boolean {
1957	  for (let i = 0; i < text.length; i += 1) {
1958	    const code = text.charCodeAt(i);
1959	    if (code >= 0xd800 && code <= 0xdbff) {
1960	      const next = text.charCodeAt(i + 1);
1961	      if (!(next >= 0xdc00 && next <= 0xdfff)) {
1962	        return true; // 高代理项后未跟低代理项
1963	      }
1964	      i += 1; // 跳过完整代理对
1965	    } else if (code >= 0xdc00 && code <= 0xdfff) {
1966	      return true; // 孤立的低代理项
1967	    }
1968	  }
1969	  return false;
1970	}
