1972	// 严格 base64：完整四字符组 + 可选末尾填充；空串合法（还原为 0 字节）
1973	const BASE64_RE = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
1974	
1975	function parseSnapshotRecord(raw: unknown, index: number, seen: Set<number>): SnapshotRequest {
1976	  const where = `records[${index}]`;
1977	  if (!isPlainObject(raw)) {
1978	    snapshotFail(where, '必须是对象');
1979	  }
1980	  const { id, request } = raw;
1981	  if (!Number.isInteger(id) || (id as number) < 1) {
1982	    snapshotFail(`${where}.id`, `必须是正整数，收到 ${JSON.stringify(id)}`);
1983	  }
1984	  if (seen.has(id as number)) {
1985	    snapshotFail(`${where}.id`, `与其他记录重复：${id as number}`);
1986	  }
1987	  seen.add(id as number);
1988	
1989	  const reqWhere = `${where}.request`;
1990	  if (!isPlainObject(request)) {
1991	    snapshotFail(reqWhere, '必须是对象');
1992	  }
1993	  const { method, target, path: recordPath, rawHeaders, bodyBytes, body } = request;
1994	  if (typeof method !== 'string') {
1995	    snapshotFail(`${reqWhere}.method`, '必须是字符串');
1996	  }
1997	  if (typeof target !== 'string') {
1998	    snapshotFail(`${reqWhere}.target`, '必须是字符串');
1999	  }
2000	  if (typeof recordPath !== 'string') {
2001	    snapshotFail(`${reqWhere}.path`, '必须是字符串');
2002	  }
2003	  // 匹配所用路径由 target 去掉查询串重新推导；与记录 path 不符说明快照不可靠
2004	  const derived = (target as string).split('?')[0];
2005	  if (derived !== recordPath) {
2006	    snapshotFail(
2007	      `${reqWhere}.path`,
2008	      `与 target 去掉查询串后的路径不符：path=${JSON.stringify(recordPath)}，target=${JSON.stringify(target)}`,
2009	    );
2010	  }
2011	  if (!Array.isArray(rawHeaders)) {
2012	    snapshotFail(`${reqWhere}.rawHeaders`, '必须是按在线顺序成对排列的字符串数组');
2013	  }
2014	  if (rawHeaders.length % 2 !== 0) {
2015	    snapshotFail(
2016	      `${reqWhere}.rawHeaders`,
2017	      `必须成对（名称、值交替），当前长度为 ${rawHeaders.length}`,
2018	    );
2019	  }
2020	  for (let j = 0; j < rawHeaders.length; j += 1) {
2021	    if (typeof rawHeaders[j] !== 'string') {
2022	      snapshotFail(`${reqWhere}.rawHeaders[${j}]`, '必须是字符串');
2023	    }
2024	  }
2025	  // 重复头取在线顺序第一项（与 Node 在线解析 content-type 的行为一致）
2026	  let contentType: string | undefined;
2027	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
2028	    if ((rawHeaders[j] as string).toLowerCase() === 'content-type') {
2029	      contentType = rawHeaders[j + 1] as string;
2030	      break;
2031	    }
2032	  }
2033	
2034	  if (!Number.isInteger(bodyBytes) || (bodyBytes as number) < 0) {
2035	    snapshotFail(`${reqWhere}.bodyBytes`, `必须是非负整数，收到 ${JSON.stringify(bodyBytes)}`);
2036	  }
2037	
2038	  const bodyWhere = `${reqWhere}.body`;
2039	  if (!isPlainObject(body)) {
2040	    snapshotFail(bodyWhere, '必须是对象（含 encoding 与 content）');
2041	  }
2042	  const { encoding, content } = body;
2043	  if (encoding !== 'utf-8' && encoding !== 'base64') {
2044	    snapshotFail(
2045	      `${bodyWhere}.encoding`,
2046	      `必须是 "utf-8" 或 "base64"，收到 ${JSON.stringify(encoding)}`,
2047	    );
2048	  }
2049	  if (typeof content !== 'string') {
2050	    snapshotFail(`${bodyWhere}.content`, '必须是字符串');
2051	  }
2052	  let bytes: Buffer;
2053	  if (encoding === 'utf-8') {
2054	    if (hasLoneSurrogate(content as string)) {
2055	      snapshotFail(
2056	        `${bodyWhere}.content`,
2057	        '含孤立代理项（lone surrogate）：按 UTF-8 重新编码会被替换字符改写，无法无损还原原始字节',
2058	      );
2059	    }
2060	    bytes = Buffer.from(content as string, 'utf8');
2061	  } else {
2062	    if (!BASE64_RE.test(content as string)) {
2063	      snapshotFail(`${bodyWhere}.content`, '不是合法的 base64 编码');
2064	    }
2065	    bytes = Buffer.from(content as string, 'base64');
2066	  }
2067	  if (bytes.byteLength !== (bodyBytes as number)) {
2068	    snapshotFail(
2069	      bodyWhere,
2070	      `按 ${encoding as string} 还原为 ${bytes.byteLength} 字节，与 bodyBytes=${bodyBytes as number} 不符：快照已丢失字节，无法无损重建`,
2071	    );
2072	  }
2073	
2074	  return {
2075	    id: id as number,
2076	    method: method as string,
2077	    target: target as string,
2078	    path: recordPath as string,
2079	    rawHeaders: rawHeaders as string[],
2080	    contentType,
2081	    body: bytes,
2082	  };
2083	}
