2085	// 快照顶层结构校验（count 与 records 数量一致）；记录逐条校验由调用方继续
2086	function snapshotRecordsOf(raw: unknown): unknown[] {
2087	  if (!isPlainObject(raw)) {
2088	    snapshotFail('', '快照顶层必须是 JSON 对象（含 count 与 records）');
2089	  }
2090	  const { count, records } = raw;
2091	  if (!Array.isArray(records)) {
2092	    snapshotFail('records', '必须是数组');
2093	  }
2094	  if (!Number.isInteger(count) || (count as number) < 0) {
2095	    snapshotFail('count', `必须是非负整数，收到 ${JSON.stringify(count)}`);
2096	  }
2097	  if ((count as number) !== records.length) {
2098	    snapshotFail('count', `与 records 数量不符：count=${count as number}，实际 ${records.length} 条`);
2099	  }
2100	  return records;
2101	}
2102	
2103	// 仅校验“重建请求所需”的字段；记录中的版本、匹配/校验结论、计划响应、
2104	// 发送状态等字段不被信任，也不参与判定，故不要求其存在。
2105	function parseSnapshot(raw: unknown): SnapshotRequest[] {
2106	  const seen = new Set<number>();
2107	  return snapshotRecordsOf(raw).map((rec, i) => parseSnapshotRecord(rec, i, seen));
2108	}
