2110	// 读取 -> 解析 -> 校验并重建；任何一步失败都抛出含文件路径与可定位原因的错误
2111	async function loadSnapshotFromFile(snapshotPath: string): Promise<SnapshotRequest[]> {
2112	  let text: string;
