2117	  }
2118	
2119	  let raw: unknown;
2120	  try {
2121	    raw = JSON.parse(text);
2122	  } catch (e) {
2123	    throw new Error(`请求记录快照文件 ${snapshotPath} 不是合法 JSON：${describeError(e)}`);
2124	  }
