2133	// 逐条判定结论：
2134	//   unmatched      —— 未匹配（无此“方法 + 字面路径”接口，或方法非 GET/POST）
2135	//   no_body_check  —— 命中接口，但该接口未配置正文规则（不解析正文）
2136	//   passed         —— 命中接口且通过正文校验
2137	//   rejected       —— 命中接口但正文被拒绝（附解析/结构差异报告）
2138	type VerifyOutcome = 'unmatched' | 'no_body_check' | 'passed' | 'rejected';
2139	
2140	interface VerifyResultEntry {
2141	  readonly id: number;
2142	  readonly outcome: VerifyOutcome;
2143	  readonly endpoint: string | null;
2144	  readonly rejection?: BodyReport;
2145	}
2146	
2147	interface VerifyReport {
2148	  readonly requestsFile: string;
2149	  readonly configFile: string;
2150	  readonly total: number;
2151	  readonly accepted: number;
2152	  readonly rejected: number;
2153	  readonly results: readonly VerifyResultEntry[];
2154	}
2155	
2156	function verifyRequests(
2157	  requests: readonly SnapshotRequest[],
2158	  specs: readonly EndpointSpec[],
2159	  requestsFile: string,
2160	  configFile: string,
2161	): VerifyReport {
2162	  const byKey = new Map<string, EndpointSpec>();
2163	  for (const spec of specs) {
2164	    byKey.set(`${spec.method} ${spec.path}`, spec);
2165	  }
2166	  const results = requests.map((req): VerifyResultEntry => {
2167	    const endpoint =
2168	      req.method === 'GET' || req.method === 'POST'
2169	        ? byKey.get(`${req.method} ${req.path}`)
2170	        : undefined;
2171	    if (!endpoint) {
2172	      return { id: req.id, outcome: 'unmatched', endpoint: null };
2173	    }
2174	    const key = `${endpoint.method} ${endpoint.path}`;
2175	    if (endpoint.bodyRule) {
2176	      const rejection = validateBodyWithContentType(req.contentType, req.body, endpoint.bodyRule);
2177	      if (rejection) {
2178	        return { id: req.id, outcome: 'rejected', endpoint: key, rejection };
2179	      }
2180	      return { id: req.id, outcome: 'passed', endpoint: key };
2181	    }
2182	    return { id: req.id, outcome: 'no_body_check', endpoint: key };
2183	  });
2184	  const accepted = results.filter(
2185	    (r) => r.outcome === 'passed' || r.outcome === 'no_body_check',
2186	  ).length;
2187	  return {
2188	    requestsFile,
2189	    configFile,
2190	    total: results.length,
2191	    accepted,
2192	    rejected: results.length - accepted,
2193	    results,
2194	  };
2195	}
