2197	async function runVerify(requestsArg: string, configArg: string): Promise<never> {
2198	  const requestsFile = path.resolve(requestsArg);
2199	  const configFile = path.resolve(configArg);
2200	
2201	  const attemptSnapshot = async (): Promise<{ requests?: SnapshotRequest[]; error?: string }> => {
2202	    try {
2203	      return { requests: await loadSnapshotFromFile(requestsFile) };
2204	    } catch (e) {
2205	      return { error: describeError(e) };
2206	    }
2207	  };
2208	  const attemptSpecs = async (): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
2209	    try {
2210	      return { specs: await loadSpecsFromFile(configFile) };
2211	    } catch (e) {
2212	      return { error: describeError(e) };
2213	    }
2214	  };
2215	
2216	  // 两份输入都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
2217	  const [snapResult, specResult] = await Promise.all([attemptSnapshot(), attemptSpecs()]);
2218	  let failed = false;
2219	  if (snapResult.error !== undefined) {
2220	    process.stderr.write(`${APP_NAME}: verify 请求快照：${snapResult.error}\n`);
2221	    failed = true;
2222	  }
2223	  if (specResult.error !== undefined) {
2224	    process.stderr.write(`${APP_NAME}: verify 场景配置：${specResult.error}\n`);
2225	    failed = true;
2226	  }
2227	  if (failed) {
2228	    process.exit(2);
2229	  }
2230	
2231	  const report = verifyRequests(
2232	    snapResult.requests as SnapshotRequest[],
2233	    specResult.specs as EndpointSpec[],
2234	    requestsFile,
2235	    configFile,
2236	  );
2237	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
2238	  process.exit(report.rejected === 0 ? 0 : 1);
2239	}
