2242	// 本机请求重放与响应差异报告（replay 子命令）
2243	// ---------------------------------------------------------------------------
2244	//
2245	// 读取 GET /__contractlab/requests 的完整 JSON 快照，按输入顺序保留原编号，
2246	// 把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口：前一条结束才发下一条，
2247	// 每次执行每条只尝试一次，不跟随重定向。仅比较实际响应的状态码与正文原始字节
2248	// 和记录中的计划响应（计划正文按 UTF-8 编码）；不比较响应头，也不依据记录版本
2249	// 与发送状态判定——pending / sent / interrupted 均可重放，400/404/500 同样按
2250	// 内容比较。不监听端口、不修改文件；已发送的请求可能已被目标处理，不重载、
2251	// 清空或回滚目标状态。
2252	//
2253	// 仅重放 GET/POST；target 须为以 "/" 开头的合法 HTTP 请求目标，原样发送
2254	// （保留查询串与百分号编码，不归一化路径）；禁止重放 /__contractlab 本身及
2255	// /__contractlab/ 前缀路径。每条记录另须有 200–599 的计划响应状态与文本正文。
2256	// 参数与全部记录（含可发送的头名称和值）有效后才连接；参数或快照失败退出 2，
2257	// stderr 给原因，stdout 为空且不发任何请求。
2258	//
2259	// 每条请求的总超时自开始连接覆盖完整收发，持续来数据也不延长；连接失败、
2260	// 超时或响应中途断开记通信失败，关闭连接后继续下一条（部分响应不算完整）。
2261	
2262	// 重放时剥离的头（小写）：原 Host / Expect / HTTP 逐跳与分帧头；
2263	// Connection 头指名的头名也一并剥离。Host 与 Content-Length 按目标和实际
2264	// 字节数重建。
2265	const REPLAY_STRIP_HEADERS: ReadonlySet<string> = new Set([
2266	  'host',
2267	  'expect',
2268	  'connection',
2269	  'keep-alive',
2270	  'content-length',
2271	  'transfer-encoding',
2272	  'te',
2273	  'trailer',
2274	  'upgrade',
2275	  'proxy-authenticate',
2276	  'proxy-authorization',
2277	]);
