2279	// 一条待重放的请求：共享快照校验之上再经重放专用校验
2280	interface ReplayRequest {
2281	  readonly id: number;
2282	  readonly method: 'GET' | 'POST';
2283	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
2284	  readonly target: string;
2285	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
2286	  readonly headers: readonly [string, string][];
